mapper.select:
SELECT c.application_name AS applicationName, IFNULL(stats.score, 0) AS score FROM (
SELECT #{clientId} AS registered_client_id
) t LEFT JOIN oauth2_client_application c ON t.registered_client_id = c.registered_client_id LEFT JOIN ( SELECT a.registered_client_id, COUNT(DISTINCT a.principal_name) AS score FROM oauth2_authorization a WHERE a.access_token_issued_at >= DATE_SUB(CURDATE(), INTERVAL DAY) AND a.access_token_issued_at < DATE_ADD(CURDATE(), INTERVAL 1 DAY) AND GROUP BY a.registered_client_id ) stats ON t.registered_client_id = stats.registered_client_id ORDER BY score DESC

SELECT c.application_name AS applicationName, IFNULL(stats.score, 0) AS score FROM (
SELECT #{clientId} AS registered_client_id
) t LEFT JOIN oauth2_client_application c ON t.registered_client_id = c.registered_client_id LEFT JOIN ( SELECT a.registered_client_id, COUNT(a.id) AS score FROM oauth2_authorization a WHERE a.create_time >= DATE_SUB(CURDATE(), INTERVAL DAY) AND a.create_time < DATE_ADD(CURDATE(), INTERVAL 1 DAY) AND GROUP BY a.registered_client_id ) stats ON t.registered_client_id = stats.registered_client_id ORDER BY score DESC
